import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import ts from 'typescript';
import { phraseKey } from '../src/lib/phrase-key.mjs';

// BudouX's public barrel imports HTML processing/linkedom. Ship only the
// unchanged pure parser + Japanese model, with upstream license headers.
const require = createRequire(import.meta.url);
const budoux = path.resolve(path.dirname(require.resolve('budoux')), '..');
const output = 'src/lib/generated';
fs.mkdirSync(output, { recursive: true });
for (const [source, target] of [['parser.js', 'budoux-parser.mjs'], ['data/models/ja.js', 'budoux-ja.mjs']]) {
  const contents = fs.readFileSync(path.join(budoux, 'module', source), 'utf8')
    .replace(/\/\/# sourceMappingURL=.*$/gm, '');
  fs.writeFileSync(path.join(output, target), contents);
}
fs.copyFileSync('scripts/licenses/BUDOUX-LICENSE', path.join(output, 'BUDOUX-LICENSE'));
fs.writeFileSync(path.join(output, 'README.md'),
  `Generated by scripts/prepare-typography.mjs from BudouX ${JSON.parse(fs.readFileSync(path.join(budoux, 'package.json'))).version}.\n` +
  'Upstream: https://github.com/google/budoux (Apache-2.0). Parser/model are unmodified; source-map comments omitted.\n' +
  'Static text boundaries are precomputed; dynamic text uses the same pure parser. Do not edit generated files.\n');
const { segmentJapanese } = await import('../src/lib/japanese-segmentation.mjs');
const strings = new Set();
const hasJapanese = /[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}]/u;
function scan(directory) {
  for (const entry of fs.readdirSync(directory, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
    const file = path.join(directory, entry.name);
    if (file === output) continue;
    if (entry.isDirectory()) scan(file);
    else if (/\.(tsx?|json)$/.test(file)) {
      const source = ts.createSourceFile(file, fs.readFileSync(file, 'utf8'), ts.ScriptTarget.Latest, true,
        file.endsWith('.tsx') ? ts.ScriptKind.TSX : ts.ScriptKind.TS);
      function visit(node) {
        if ((ts.isStringLiteralLike(node) || ts.isJsxText(node)) && hasJapanese.test(node.text)) {
          strings.add(node.text);
          strings.add(node.text.trim());
        }
        ts.forEachChild(node, visit);
      }
      visit(source);
    }
  }
}
// Cache the shared first-view UI. Article bodies are already rendered at build
// time; lazy demos retain the small pure-parser fallback instead of a site-wide dictionary.
for (const dir of ['site', 'ui', 'characters', 'sections', 'assistant']) scan(`src/components/${dir}`);
const cache = {};
const owners = new Map();
for (const text of [...strings].sort()) {
  const key = phraseKey(text);
  if (owners.has(key) && owners.get(key) !== text) throw new Error('Phrase cache collision');
  owners.set(key, text);
  let offset = 0;
  cache[key] = segmentJapanese(text).slice(0, -1).map(phrase => (offset += phrase.length));
}
fs.writeFileSync(path.join(output, 'japanese-boundaries.json'), JSON.stringify(cache) + '\n');
console.log(`Precomputed Japanese boundaries: ${strings.size} strings, ${fs.statSync(path.join(output, 'japanese-boundaries.json')).size} bytes; no DOM parser in browser entry.`);
